import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

type DocumentKind = "w9" | "insurance_certificate" | "contract";

interface DocumentOut {
  id: string;
  vendor_id: string;
  kind: DocumentKind;
  status: "processing" | "extracted" | "failed";
}

interface ExtractionOut {
  id: string;
  document_id: string;
  status: "pending_review" | "approved" | "rejected";
}

interface VendorOut {
  id: string;
  status: "draft" | "in_review" | "approved" | "rejected";
}

interface AuditTrail {
  items: { action: string }[];
}

const KINDS: DocumentKind[] = ["w9", "insurance_certificate", "contract"];

function uniqueSuffix(): string {
  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

/** Polls a document until extraction finishes (or fails the test). */
async function waitForExtracted(member: APIRequestContext, documentId: string): Promise<DocumentOut> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const doc = await expectStatus<DocumentOut>(await member.get(`/api/documents/${documentId}`), 200);
    if (doc.status === "extracted") return doc;
    if (doc.status === "failed") throw new Error(`document ${documentId} extraction failed`);
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} did not finish extraction in time`);
}

test("approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs }) => {
  // Arrange: a vendor in review with three pending extractions, built through the API.
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const suffix = uniqueSuffix();

  const vendor = await expectStatus<VendorOut>(
    await member.post("/api/vendors", {
      data: {
        name: `REV-05 Vendor ${suffix}`,
        category: "services",
        contact_email: `rev05-${suffix}@example.test`,
      },
    }),
    201,
  );

  const documentIds: string[] = [];
  for (const kind of KINDS) {
    const doc = await expectStatus<DocumentOut>(
      await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind,
          file: {
            name: `${kind}-${suffix}.pdf`,
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 REV-05 fixture"),
          },
        },
      }),
      201,
    );
    documentIds.push(doc.id);
  }

  for (const documentId of documentIds) {
    await waitForExtracted(member, documentId);
  }

  const submitted = await expectStatus<VendorOut>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  expect(submitted.status).toBe("in_review");

  const extractionIds: string[] = [];
  for (const documentId of documentIds) {
    const extraction = await expectStatus<ExtractionOut>(
      await reviewer.get(`/api/documents/${documentId}/extraction`),
      200,
    );
    expect(extraction.status).toBe("pending_review");
    extractionIds.push(extraction.id);
  }
  expect(extractionIds).toHaveLength(3);

  // Act: the reviewer approves all three extractions.
  for (const extractionId of extractionIds) {
    const decided = await expectStatus<ExtractionOut>(
      await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "approve", note: `REV-05 approval ${suffix}` },
      }),
      200,
    );
    expect(decided.status).toBe("approved");
  }

  // Assert: the vendor is approved and the audit trail records vendor.approved.
  const finalVendor = await expectStatus<VendorOut>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(finalVendor.status).toBe("approved");

  const audit = await expectStatus<AuditTrail>(await reviewer.get(`/api/vendors/${vendor.id}/audit`), 200);
  expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
});
